Cancel</button><button class="btn-primary" id="savePlan">Publish Plan</button></div></form></div></div>
<script>const modal=document.getElementById('planModal'),form=document.getElementById('planForm');function setField(key,value){const nodes=[...form.querySelectorAll(`[name="${key}"]`)];if(!nodes.length)return;const checkbox=nodes.find(node=>node.type==='checkbox');if(checkbox){checkbox.checked=value===true||value===1||value==='1';return}const input=nodes[0];if(key==='features'){input.value=(value||[]).join('\n');return}if(key==='gst_percentage'&&value!==null&&value!==''){input.value=String(parseFloat(value));return}input.value=value??''}function openPlan(plan=null){form.reset();form.action='{{ route('payments-plans.store') }}';form.querySelector('[name=_method]')?.remove();document.getElementById('modalTitle').textContent=plan?'Edit Plan':'Create New Plan';document.getElementById('savePlan').textContent=plan?'Save Plan':'Publish Plan';if(plan){form.action=`{{ url('payments-plans') }}/${plan.id}`;form.insertAdjacentHTML('afterbegin','<input type="hidden" name="_method" value="PUT">');Object.entries(plan).forEach(([key,value])=>setField(key,value))}modal.classList.add('open')}document.getElementById('openPlanModal').onclick=()=>openPlan();document.getElementById('closePlanModal').onclick=document.getElementById('cancelPlanModal').onclick=()=>modal.classList.remove('open');document.querySelectorAll('.edit-plan').forEach(button=>button.onclick=()=>openPlan(JSON.parse(button.dataset.plan)));modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open')};</script>
